using namespace std;

/*
A set of dominoes can be arranged in one straight chain using all pieces
iff the multigraph formed by numbers as vertices and dominoes as edges
has:
1) all vertices with nonzero degree in a single connected component
2) exactly 0 or 2 vertices of odd degree

Input format is not explicitly given, so we support a common simple format:
- First number: n
- Then n dominoes, each as two integers a b

Numbers on dominoes are assumed to be standard domino values [0..6], but this
solution also works for any nonnegative integers appearing in input.

Output:
- "Yes" if arrangement is possible
- "No" otherwise
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    unordered_map<int, int> deg;
    unordered_map<int, vector<int>> g;
    vector<pair<int,int>> edges;

    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        edges.push_back({a, b});
        deg[a]++;
        deg[b]++;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    if (n == 0) {
        cout << "Yes\n";
        return 0;
    }

    // Find a vertex with nonzero degree
    int start = -1;
    for (auto &p : deg) {
        if (p.second > 0) {
            start = p.first;
            break;
        }
    }

    // Connectivity check among nonzero-degree vertices
    unordered_set<int> vis;
    queue<int> q;
    q.push(start);
    vis.insert(start);

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int to : g[v]) {
            if (!vis.count(to)) {
                vis.insert(to);
                q.push(to);
            }
        }
    }

    for (auto &p : deg) {
        if (p.second > 0 && !vis.count(p.first)) {
            cout << "No\n";
            return 0;
        }
    }

    int odd = 0;
    for (auto &p : deg) {
        if (p.second % 2) odd++;
    }

    cout << ((odd == 0 || odd == 2) ? "Yes\n" : "No\n");
    return 0;
}

