public class Main {
    static int[] parent;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int x, int y) {
        parent[find(x)] = find(y);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder sb = new StringBuilder();

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            int n = Integer.parseInt(line);
            int[] degree = new int[7];
            parent = new int[7];
            for (int i = 0; i < 7; i++) parent[i] = i;
            boolean[] hasNode = new boolean[7];

            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().trim().split("\\s+");
                int a = Integer.parseInt(parts[0]);
                int b = Integer.parseInt(parts[1]);
                degree[a]++;
                degree[b]++;
                hasNode[a] = true;
                hasNode[b] = true;
                union(a, b);
            }

            // Check connectivity among nodes that appear
            int root = -1;
            boolean connected = true;
            for (int i = 0; i < 7; i++) {
                if (hasNode[i]) {
                    if (root == -1) root = find(i);
                    else if (find(i) != root) {
                        connected = false;
                        break;
                    }
                }
            }

            // Count odd degree nodes
            int oddCount = 0;
            for (int i = 0; i < 7; i++) {
                if (degree[i] % 2 == 1) oddCount++;
            }

            if (n == 0) {
                sb.append("Yes\n");
            } else if (connected && (oddCount == 0 || oddCount == 2)) {
                sb.append("Yes\n");
            } else {
                sb.append("No\n");
            }
        }

        System.out.print(sb);
    }
}

import java.io.*;
