public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        int[] deg = new int[7];
        boolean[] present = new boolean[7];
        boolean[][] adj = new boolean[7][7];

        for (int i = 0; i < n; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();

            if (a == b) {
                deg[a] += 2;
            } else {
                deg[a]++;
                deg[b]++;
                adj[a][b] = adj[b][a] = true;
            }
            present[a] = true;
            present[b] = true;
        }

        int start = -1;
        for (int i = 0; i <= 6; i++) {
            if (deg[i] > 0) {
                start = i;
                break;
            }
        }

        if (start == -1) {
            System.out.println("Yes");
            return;
        }

        boolean[] vis = new boolean[7];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(start);
        vis[start] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v <= 6; v++) {
                if (adj[u][v] && !vis[v]) {
                    vis[v] = true;
                    q.add(v);
                }
            }
        }

        for (int i = 0; i <= 6; i++) {
            if (deg[i] > 0 && !vis[i]) {
                System.out.println("No");
                return;
            }
        }

        int odd = 0;
        for (int i = 0; i <= 6; i++) {
            if ((deg[i] & 1) == 1) odd++;
        }

        System.out.println(odd == 0 || odd == 2 ? "Yes" : "No");
    }
}
